<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('contacts.manage');
$id=max(0,(int)($_GET['id']??$_POST['id']??0));$contact=null;if($id){$s=db()->prepare('SELECT * FROM contacts WHERE id=?');$s->execute([$id]);$contact=$s->fetch();if(!$contact){http_response_code(404);exit('Contacto no encontrado.');}}
$pageTitle=$contact?'Editar contacto':'Nuevo contacto';$errors=[];$clients=db()->query('SELECT id,company_name,country FROM clients ORDER BY company_name')->fetchAll();$users=db()->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();
$v=fn(string$key,mixed$default='')=>$_POST[$key]??($contact[$key]??$default);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$first=trim((string)($_POST['first_name']??''));$last=trim((string)($_POST['last_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$language=(string)($_POST['language']??'es');$status=(string)($_POST['status']??'active');if($first==='')$errors[]='El nombre es obligatorio.';if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='El email no es válido.';if(!in_array($language,['es','pt','en'],true))$language='es';if(!in_array($status,['active','inactive','lead'],true))$status='active';$data=[max(0,(int)($_POST['client_id']??0))?:null,$first,$last?:null,trim((string)($_POST['job_title']??''))?:null,trim((string)($_POST['department']??''))?:null,$email?:null,trim((string)($_POST['secondary_email']??''))?:null,trim((string)($_POST['phone']??''))?:null,trim((string)($_POST['whatsapp']??''))?:null,$language,$status,trim((string)($_POST['source']??''))?:null,trim((string)($_POST['notes']??''))?:null,max(0,(int)($_POST['owner_user_id']??0))?:null];if(!$errors){if($id){db()->prepare('UPDATE contacts SET client_id=?,first_name=?,last_name=?,job_title=?,department=?,email=?,secondary_email=?,phone=?,whatsapp=?,language=?,status=?,source=?,notes=?,owner_user_id=? WHERE id=?')->execute([...$data,$id]);}else{db()->prepare('INSERT INTO contacts(client_id,first_name,last_name,job_title,department,email,secondary_email,phone,whatsapp,language,status,source,notes,owner_user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($data);$id=(int)db()->lastInsertId();}log_activity($contact?'Contacto actualizado':'Contacto creado',(int)($data[0]??0),null,trim($first.' '.$last));flash('success','Contacto guardado correctamente.');redirect('contact_view.php?id='.$id);}}
require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2><?=$contact?'Actualizar contacto':'Crear contacto'?></h2><span class="table-sub">Una persona puede estar vinculada a una empresa, negocio y responsable.</span></div><a class="btn btn-light btn-small" href="contacts.php">Volver</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Nombre *<input name="first_name" required value="<?=e($v('first_name'))?>"></label><label>Apellido<input name="last_name" value="<?=e($v('last_name'))?>"></label><label>Empresa<select name="client_id"><option value="0">Contacto independiente</option><?php foreach($clients as$c):?><option value="<?=$c['id']?>" <?=(int)$v('client_id')===(int)$c['id']?'selected':''?>><?=e($c['company_name'])?> · <?=e($c['country'])?></option><?php endforeach;?></select></label><label>Cargo<input name="job_title" value="<?=e($v('job_title'))?>"></label><label>Departamento<input name="department" value="<?=e($v('department'))?>"></label><label>Responsable<select name="owner_user_id"><option value="0">Sin asignar</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=(int)$v('owner_user_id',$_SESSION['user_id'])===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Email<input type="email" name="email" value="<?=e($v('email'))?>"></label><label>Email secundario<input type="email" name="secondary_email" value="<?=e($v('secondary_email'))?>"></label><label>Teléfono<input name="phone" value="<?=e($v('phone'))?>"></label><label>WhatsApp<input name="whatsapp" value="<?=e($v('whatsapp'))?>"></label><label>Idioma<select name="language"><?php foreach(crm_supported_languages() as$code=>$label):?><option value="<?=$code?>" <?=$v('language','es')===$code?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Estado<select name="status"><option value="active" <?=$v('status','active')==='active'?'selected':''?>>Activo</option><option value="lead" <?=$v('status')==='lead'?'selected':''?>>Lead</option><option value="inactive" <?=$v('status')==='inactive'?'selected':''?>>Inactivo</option></select></label><label>Origen<input name="source" value="<?=e($v('source'))?>" placeholder="Web, LinkedIn, referido..."></label><label class="full">Notas<textarea name="notes"><?=e($v('notes'))?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="contacts.php">Cancelar</a><button class="btn btn-primary">GUARDAR CONTACTO</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
